def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x, color))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            comps.append(comp)
    if not comps:
        return [row[:] for row in grid]
    top = min(y for comp in comps for y, x, color in comp)
    out = [[0] * w for _ in range(h)]
    for comp in comps:
        shift = min(y for y, x, color in comp) - top
        for y, x, color in comp:
            out[y-shift][x] = color
    return out
